for (const sayfalar of Object.values(altSayfalar)) {
    for (const sayfa of sayfalar) {
        const ekParagraf = fazBSektorEkParagraflari[sayfa.slug];
        if (ekParagraf) sayfa.paragraflar.push(ekParagraf + (fazBSektorTamamlama[sayfa.slug] ?? ""));
        const kararEkParagraf = fazCKararEkParagraflari[sayfa.slug];
        if (kararEkParagraf) sayfa.paragraflar.push(kararEkParagraf);
    }
}

